const fail=(ok,reason)=>{if(!ok)throw Error('S30_PARTIAL_38_PROOF '+reason)};
const sha=x=>crypto.createHash('sha256').update(JSON.stringify(x)).digest('hex');
function validateProof(){
 const b=DOC.batch,ex=DOC.expected;
 fail(DOC.version===1&&b.id==='review-s30-partial-source-prefix-38-20261121'&&
  b.reviewedOn==='2026-11-21'&&b.rule===RULE&&b.entries.length===38&&
  ex.rows===38&&ex.qualifiers===35&&ex.finals===3&&
  ex.qualifierAdvances===29&&ex.personalPrize===300&&ex.groups===5,
  'manifest metadata changed');
 const tournament=JSON.parse(fs.readFileSync(path.join(ROOT,'tournaments.json'),'utf8')).catalog.find(t=>t.id===TOURNAMENT);
 const rule=JSON.parse(fs.readFileSync(path.join(ROOT,'tournament-rules.json'),'utf8')).rules.find(t=>t.id===TOURNAMENT);
 fail(tournament&&tournament.seasonId==='S30'&&tournament.team==='solo'&&
  tournament.mode==='zero-build'&&tournament.sourceEventIds.includes(EVENT)&&
  rule&&rule.source===RULE&&rule.matchCaps?.['予選']===7&&
  rule.matchCaps?.['賞金決勝']===3,
  'rule or tournament master differs');
 const ids=new Set(),places=new Set(),groups=new Set();
 for(let i=0;i<GOLD.length;i++){
  const g=GOLD[i],p=b.entries[i],s=p?.source,e=p?.expected;
  fail(s&&e&&!ids.has(g.id),'missing or repeated candidate '+g.id);
  ids.add(g.id);
  for(const key of ['id','date','region','player','event','round','kind','rank',
   'points','kills','vrs','matches','prize','source'])
   fail(s[key]===g[key],'source evidence '+g.id+' '+key);
  fail(s.playerRaw===g.raw&&s.verified===true&&s.reviewOnly!==true&&
   s.reviewReason==='順位表の取得が完了していません'&&
   s.seasonId==='S30'&&s.chapter===5&&s.season===3&&
   s.tournamentId===TOURNAMENT&&e.kind===g.expectedKind&&
   e.round===g.expectedRound&&e.prize===g.award&&
   e.qualification===g.qualification,'screenshot/source snapshot changed '+g.id);
  const url=new URL(s.source),window=url.searchParams.get('round');
  const roundNo=g.kind==='賞金決勝'?2:1;
  const eventNo=Number(g.round.match(/^Event (\d+) · Round [12] \//u)?.[1]);
  const expectedWindow=EVENT+'_Event'+eventNo+'Round'+roundNo+'_'+g.region;
  fail(Number.isInteger(eventNo)&&url.protocol==='https:'&&
   url.hostname==='www.fortnite.com'&&url.pathname==='/competitive/events/'+EVENT+'/'&&
   url.searchParams.get('region')===g.region&&window===expectedWindow&&
   url.searchParams.size===2,'untrusted official source window '+g.id);
  const place=window+'/'+g.rank;
  fail(!places.has(place),'repeated rank in the same board '+g.id);
  places.add(place);groups.add(window);
  fail(Number.isSafeInteger(g.rank)&&g.rank>0&&
   Number.isSafeInteger(g.points)&&g.points>=0&&
   Number.isSafeInteger(g.kills)&&g.kills>=0&&
   Number.isSafeInteger(g.vrs)&&g.vrs>=0&&
   Number.isSafeInteger(g.matches)&&g.matches>=1&&
   g.vrs<=g.matches&&g.matches<=(roundNo===2?3:7),
   'invalid rank, games, kill or VR '+g.id);
  const cutoff=CUTOFF[g.region],advanced=Boolean(cutoff&&g.rank<=cutoff);
  if(roundNo===2)fail(g.region==='OCE'&&g.date==='2024-06-10'&&
    g.kind==='賞金決勝'&&g.vrs===1&&g.points===100&&g.prize===null&&
    g.award===100&&e.qualification===null,'one-VR cash finalist proof '+g.id);
  else fail((g.region==='NAC'||g.region==='BR')&&
    g.kind==='予選'&&g.prize===0&&g.award===0&&
    e.qualification===(advanced?'advanced':'not-advanced')&&
    e.round===(advanced?g.round.replace('/ 予選','/ 予選突破'):g.round),
    'round1 advancement must follow official cutoff '+g.id);
 }
 fail(groups.size===5&&
  b.entries.filter(x=>x.expected.kind==='予選').length===35&&
  b.entries.filter(x=>x.expected.qualification==='advanced').length===29&&
  b.entries.reduce((n,x)=>n+x.expected.prize,0)===300,
  'selection totals or groups altered');
 return true;
}
function project(item,observedPages){
 const s=item.source,e=item.expected,{reviewOnly:_r,reviewReason:_reason,...raw}=s;
 const final=e.kind==='賞金決勝';
 const detail=final?
   '公式S30 ZB Solo Victory Cup Round2。1VRごとに個人$100。':
   e.qualification==='advanced'?
   '公式S30 ZB Solo Victory Cup Round1。'+s.region+'の規定順位内のため予選突破。予選賞金は$0。':
   '公式S30 ZB Solo Victory Cup Round1。'+s.region+'の規定順位外、予選参加のみ。賞金$0。';
 return {...raw,round:e.round,kind:e.kind,prize:e.prize,
  ...(final?{prizePerPlayer:e.prize,teamPrize:e.prize}:{}),
  note:'保存済みEpic/Osirion本人ID順位表の正常な先頭'+observedPages+'ページで'+s.player+' '+s.rank+
   '位、'+s.points+'pt、'+s.matches+'試合、'+s.kills+'K、'+s.vrs+'VRを検証。'+
   '全ページの取得完了とは扱わない。'+detail+'実際の振込完了は未確認。'+
   ' 大会元: '+s.source+' 公式規則: '+RULE};
}
function approval(item,row){
 const s=item.source;return {id:s.id,recordId:s.id,decision:'published',
  policy:POLICY,approvedAt:'2026-11-21T14:31:52Z',
  approvedBy:'Owner-authorized; original Epic account-ID and mature ordered prefix audit',
  source:s.source,rule:RULE,originalHash:sha(item),recordHash:sha(row),
  evidence:'Saved exact Epic account identity and rank, valid mature contiguous prefix, S30 region advancement cutoff, Round2 1VR=$100'};
}
function verifyRow(row,entry){
 const item=DOC.batch.entries.find(x=>x.source.id===row?.id);
 return Boolean(item&&entry&&entry.id===row.id&&entry.recordId===row.id&&
  entry.decision==='published'&&entry.policy===POLICY&&
  entry.source===item.source.source&&entry.rule===RULE&&
  entry.originalHash===sha(item)&&entry.recordHash===sha(row)&&
  row.verified===true&&
  /^保存済みEpic\/Osirion本人ID順位表/.test(row.note)&&
  Boolean(row.note.match(/先頭(\d+\/\d+)ページ/u))&&
  JSON.stringify(row)===JSON.stringify(project(item,row.note.match(/先頭(\d+\/\d+)ページ/u)[1])));
}
validateProof();
